INSERT INTO SIAC_CCA_BEFORE_DEMO.administrative_access.Transactional_Configuraciones
( Nombre, Descripcion, Valor, Tipo_Configuracion)
VALUES( N'ACTUALIZACION_FOOTER', N'Textop mostrado en la parte inferior del formulario de actualizacion de estudiantes, abajo de las opciones', N'<p class="MsoNormal" style="text-align:justify"><a name="_Hlk212040091"><span lang="ES-NI">Para <b>finalizar el proceso de Matrícula 2026</b> y que el
estudiante <b>aparezca en Listas oficiales al inicio de clases</b>, al momento
de pagar su matrícula debe presentar en físico o digital la póliza de seguro.<o:p></o:p></span></a></p>

<p class="MsoNormal" style="text-align:justify"><span lang="ES-NI">Los seguros serán con Seguros LAFISE (correduría Karelia Lovo), por
un valor de <b>C$1,835</b> el cual será cargado en <b>5 cuotas</b> de <b>C$367</b>
cada una en los <b>meses de febrero a junio 2026</b>.<o:p></o:p></span></p>

<p class="MsoNormal" style="text-align:justify"><span lang="ES-NI">Para los pagos de <b>Matrícula 2026 por Transferencias, Depósitos
bancarios o Débitos automáticos</b>, se debe <b>enviar correo de comprobante y
de póliza de seguro vigente</b> hasta diciembre 2026 al correo: <b>caja@cca.edu.ni</b></span><span lang="ES-NI"><o:p></o:p></span></p>', N'TEMPLATE');



